-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.garage_car_stats(p_cars uuid[])
 RETURNS TABLE(car_id uuid, mods integer, updates integer, latest_update jsonb, parts_live integer, parts_held integer, parts_sold integer, open_offers integer, followers integer, likes integer, sales_count integer, sales_cents bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with mine as (
    select c.id from public.cars c
    where c.id = any(p_cars) and c.owner_id = auth.uid()
  ),
  mod_counts as (
    select m.car_id, count(*)::integer as n
    from public.mod_items m join mine on mine.id = m.car_id
    where m.status = 'installed'
    group by m.car_id
  ),
  post_counts as (
    select p.car_id, count(*)::integer as n
    from public.activity_posts p join mine on mine.id = p.car_id
    where p.published_at is not null
    group by p.car_id
  ),
  latest as (
    select distinct on (p.car_id)
      p.car_id,
      jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'intro', p.intro,
        'body', p.body,
        'published_at', p.published_at,
        'cover_url', (
          select ai.url from public.activity_images ai
          where ai.post_id = p.id order by ai.position limit 1
        )
      ) as post
    from public.activity_posts p join mine on mine.id = p.car_id
    where p.published_at is not null
    order by p.car_id, p.published_at desc, p.id desc
  ),
  parts as (
    select
      l.source_car_id as car_id,
      count(*) filter (where l.status = 'active')::integer as live,
      count(*) filter (where l.status = 'reserved')::integer as held,
      count(*) filter (where l.status = 'sold')::integer as sold,
      coalesce(sum((
        select count(*) from public.offers o
        where o.listing_id = l.id and o.status = 'open'
      )) filter (where l.status <> 'sold'), 0)::integer as offers
    from public.listings l join mine on mine.id = l.source_car_id
    where l.status in ('active', 'reserved', 'sold')
    group by l.source_car_id
  ),
  follow_counts as (
    select f.target_id as car_id, count(*)::integer as n
    from public.follows f join mine on mine.id = f.target_id
    where f.target_type = 'car'
    group by f.target_id
  ),
  like_counts as (
    select k.target_id as car_id, count(*)::integer as n
    from public.likes k join mine on mine.id = k.target_id
    where k.target_type = 'car'
    group by k.target_id
  ),
  -- Every unit the caller sold on DRVN, at the price the buyer paid.
  sold_items as (
    select
      oi.id as item_id,
      oi.order_id,
      coalesce(
        case when (oi.commercial_snapshot -> 'source_car' ->> 'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             then (oi.commercial_snapshot -> 'source_car' ->> 'id')::uuid end,
        l.source_car_id
      ) as car_id,
      oi.price_cents::bigint as unit_cents,
      greatest(coalesce(oi.quantity, 1), 1) as quantity,
      oi.price_cents::bigint * greatest(coalesce(oi.quantity, 1), 1) as goods_cents
    from public.orders o
    join public.order_items oi on oi.order_id = o.id
    left join public.listings l on l.id = oi.listing_id
    where o.seller_id = auth.uid()
      and o.status in ('paid', 'shipped', 'delivered', 'completed')
  ),
  -- A completed return's refund belongs to the returned units: up to their
  -- goods value (a return refund also carries a shipping share), split
  -- across the return's lines in whole cents. Read from the return itself —
  -- refund_operations isn't visible to the seller — and step 2 caps it by
  -- what the order actually shows as refunded.
  returned_lines as (
    select r.id as return_id, s.item_id, s.order_id,
           s.unit_cents * least(ri.quantity, s.quantity) as weight,
           greatest(coalesce(r.refund_amount_cents, 0) - coalesce(r.label_deduction_cents, 0), 0)::bigint as refund_cents
    from public.returns r
    join public.return_items ri on ri.return_id = r.id
    join sold_items s on s.item_id = ri.order_item_id
    where r.status = 'completed'
  ),
  return_shares as (
    select q.*, least(q.refund_cents, (sum(q.weight) over (partition by q.return_id))::bigint) as total,
           (sum(q.weight) over (partition by q.return_id))::bigint as weights
    from returned_lines q
  ),
  return_alloc as (
    select a.item_id, a.order_id,
           a.floor_cents + case when row_number() over (
             partition by a.return_id order by a.remainder desc, a.item_id
           ) <= a.total - (sum(a.floor_cents) over (partition by a.return_id))::bigint then 1 else 0 end as cents
    from (
      select x.*, case when x.weights > 0 then (x.total * x.weight) / x.weights else 0 end as floor_cents,
             case when x.weights > 0 then (x.total * x.weight) % x.weights else 0 end as remainder
      from return_shares x
    ) a
  ),
  -- The order's confirmed refunds that can be goods refunds: never more
  -- than the goods themselves, and not the shipping share of a completed
  -- return's refund (the part beyond its returned goods).
  return_shipping as (
    select q.order_id, (sum(q.refund_cents - q.total))::bigint as cents
    from (select distinct on (return_id) order_id, refund_cents, total from return_shares order by return_id) q
    group by q.order_id
  ),
  order_refunds as (
    select s.order_id,
           least(greatest(coalesce(o.refunded_cents, 0)::bigint - coalesce(rs.cents, 0), 0),
                 (sum(s.goods_cents))::bigint) as goods_refund
    from sold_items s
    join public.orders o on o.id = s.order_id
    left join return_shipping rs on rs.order_id = s.order_id
    group by s.order_id, o.refunded_cents, rs.cents
  ),
  item_returns as (
    select s.item_id, s.order_id,
           least(coalesce((sum(ra.cents))::bigint, 0), s.goods_cents) as cents
    from sold_items s left join return_alloc ra on ra.item_id = s.item_id
    group by s.item_id, s.order_id, s.goods_cents
  ),
  -- Item-attributed refunds can't exceed what the order still shows as
  -- refunded (a late refund failure gives money back): cap them per order,
  -- again in whole cents.
  specific as (
    select a.item_id, a.order_id,
           a.floor_cents + case when row_number() over (
             partition by a.order_id order by a.remainder desc, a.item_id
           ) <= a.total - (sum(a.floor_cents) over (partition by a.order_id))::bigint then 1 else 0 end as cents
    from (
      select x.*, case when x.weights > 0 then (x.total * x.cents) / x.weights else 0 end as floor_cents,
             case when x.weights > 0 then (x.total * x.cents) % x.weights else 0 end as remainder
      from (
        select ir.item_id, ir.order_id, ir.cents,
               (sum(ir.cents) over (partition by ir.order_id))::bigint as weights,
               least((sum(ir.cents) over (partition by ir.order_id))::bigint, r.goods_refund) as total
        from item_returns ir join order_refunds r on r.order_id = ir.order_id
      ) x
    ) a
  ),
  -- Whatever refund no return explains is shared across what's left of the
  -- order's goods by value — floor each share, then hand out the leftover
  -- cents by largest remainder (ties by item id). The shares add up to the
  -- refund exactly, to the cent.
  general as (
    select a.item_id,
           a.floor_cents + case when row_number() over (
             partition by a.order_id order by a.remainder desc, a.item_id
           ) <= a.total - (sum(a.floor_cents) over (partition by a.order_id))::bigint then 1 else 0 end as cents
    from (
      select x.*, case when x.weights > 0 then (x.total * x.weight) / x.weights else 0 end as floor_cents,
             case when x.weights > 0 then (x.total * x.weight) % x.weights else 0 end as remainder
      from (
        select s.item_id, s.order_id,
               s.goods_cents - sp.cents as weight,
               (sum(s.goods_cents - sp.cents) over (partition by s.order_id))::bigint as weights,
               r.goods_refund - (sum(sp.cents) over (partition by s.order_id))::bigint as total
        from sold_items s
        join specific sp on sp.item_id = s.item_id
        join order_refunds r on r.order_id = s.order_id
      ) x
    ) a
  ),
  sales as (
    select s.car_id,
           count(*) filter (where s.goods_cents - sp.cents - g.cents > 0)::integer as n,
           sum(s.goods_cents - sp.cents - g.cents)::bigint as cents
    from sold_items s
    join specific sp on sp.item_id = s.item_id
    join general g on g.item_id = s.item_id
    join mine on mine.id = s.car_id
    group by s.car_id
  )
  select
    mine.id,
    coalesce(mod_counts.n, 0),
    coalesce(post_counts.n, 0),
    latest.post,
    coalesce(parts.live, 0),
    coalesce(parts.held, 0),
    coalesce(parts.sold, 0),
    coalesce(parts.offers, 0),
    coalesce(follow_counts.n, 0),
    coalesce(like_counts.n, 0),
    coalesce(sales.n, 0),
    coalesce(sales.cents, 0)
  from mine
  left join mod_counts on mod_counts.car_id = mine.id
  left join post_counts on post_counts.car_id = mine.id
  left join latest on latest.car_id = mine.id
  left join parts on parts.car_id = mine.id
  left join follow_counts on follow_counts.car_id = mine.id
  left join like_counts on like_counts.car_id = mine.id
  left join sales on sales.car_id = mine.id;
$function$;

grant execute on function public.garage_car_stats(p_cars uuid[]) to authenticated;
grant execute on function public.garage_car_stats(p_cars uuid[]) to service_role;
